export function scoreOpportunity(opportunity: Opportunity): FitScore {
  const delivery = classifyDeliveryModel(opportunity);
  if (delivery.model !== "project_delivery") {
    return {
      score: delivery.model === "unclear" ? 45 : 25,
      recommendation: "hold",
      deliveryModel: delivery.model,
      reasons: delivery.reasons,
      cautions:
        delivery.model === "unclear"
          ? ["납품형 개발 프로젝트 여부 확인 전에는 기술 적합도를 평가하지 않습니다."]
